class Point {
public:
    double x, y;

    // Constructor
    Point(double x = 0.0, double y = 0.0) : x(x), y(y) {}

    // Getters
    double getX() const { return x; }
    double getY() const { return y; }

    // Setters
    void setX(double newX) { x = newX; }
    void setY(double newY) { y = newY; }

    // Method to calculate distance from another point
    double distanceTo(const Point& other) const {
        return std::sqrt(std::pow(this->x - other.x, 2) + std::pow(this->y - other.y, 2));
    }
};
```

This class `Point` in C++ defines a point in two-dimensional space with coordinates `(x, y)`. It includes constructors, getters, setters, and a method to calculate the Euclidean distance to another `Point` object.

